package io.github.diodeme.ji.relay;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.security.KeyPairGenerator;
import java.security.SecureRandom;
import java.security.Signature;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.Set;
import org.junit.jupiter.api.Test;

final class RelayPairingServiceTest {
    private static final Instant NOW = Instant.parse("2026-09-05T12:00:00Z");

    @Test
    void ownerBootstrapIsOneUseAndInvitationRequiresOwnerConfirmation() throws Exception {
        var store = new MemoryRelayMetadataStore();
        var service = new RelayPairingService(store, Clock.fixed(NOW, ZoneOffset.UTC), seeded());
        var ownerKeys = KeyPairGenerator.getInstance("Ed25519").generateKeyPair();
        var bootstrap = service.issueOwnerBootstrap("tenant-1");
        service.claimOwner("tenant-1", bootstrap.pin(), bootstrap.secret(), "owner-1",
                ownerKeys.getPublic().getEncoded());
        assertThrows(SecurityException.class, () -> service.claimOwner("tenant-1", bootstrap.pin(),
                bootstrap.secret(), "owner-2", ownerKeys.getPublic().getEncoded()));

        var invitation = service.invite("tenant-1", "owner-1", Set.of("host-1"));
        var phoneKeys = KeyPairGenerator.getInstance("Ed25519").generateKeyPair();
        assertThrows(SecurityException.class, () -> service.accept("tenant-1", invitation.invitationId(),
                invitation.secret(), "phone-1", phoneKeys.getPublic().getEncoded()));
        assertFalse(service.confirm("tenant-1", invitation.invitationId(), "owner-1", "wrong"));
        assertTrue(service.confirm("tenant-1", invitation.invitationId(), "owner-1", invitation.fingerprint()));
        service.accept("tenant-1", invitation.invitationId(), invitation.secret(), "phone-1",
                phoneKeys.getPublic().getEncoded());
        assertTrue(store.grant("tenant-1", "host-1", "phone-1").isPresent());
        assertTrue(store.grant("tenant-1", "host-2", "phone-1").isEmpty());
        assertThrows(SecurityException.class, () -> service.accept("tenant-1", invitation.invitationId(),
                invitation.secret(), "phone-2", phoneKeys.getPublic().getEncoded()));
    }

    @Test
    void challengeIsConnectionBoundOneUseAndRevocationFailsClosed() throws Exception {
        var store = new MemoryRelayMetadataStore();
        var keys = KeyPairGenerator.getInstance("Ed25519").generateKeyPair();
        store.saveDevice(new RelayMetadataStore.Device("tenant-1", "device-1", keys.getPublic().getEncoded(),
                Set.of(RelayRole.RELAY_OWNER), NOW, java.util.Optional.empty()));
        var challenges = new DeviceChallengeService(store, Clock.fixed(NOW, ZoneOffset.UTC), seeded());
        var challenge = challenges.issue("tenant-1", "device-1", "connection-1");
        Signature signer = Signature.getInstance("Ed25519");
        signer.initSign(keys.getPrivate());
        signer.update(DeviceChallengeService.payload("tenant-1", "device-1", "connection-1", challenge.nonce()));
        byte[] signature = signer.sign();
        assertTrue(challenges.verify("tenant-1", "device-1", "connection-1", signature));
        assertFalse(challenges.verify("tenant-1", "device-1", "connection-1", signature));
        store.revokeDevice("tenant-1", "device-1", NOW.plusSeconds(1));
        assertThrows(SecurityException.class,
                () -> challenges.issue("tenant-1", "device-1", "connection-2"));
    }

    @Test
    void tenantScopesDoNotLeakMetadata() {
        var store = new MemoryRelayMetadataStore();
        byte[] key = [REDACTED_CREDENTIAL] byte[32];
        store.saveDevice(new RelayMetadataStore.Device("tenant-a", "same", key, Set.of(), NOW,
                java.util.Optional.empty()));
        assertEquals(1, store.devices("tenant-a").size());
        assertTrue(store.devices("tenant-b").isEmpty());
        assertTrue(store.device("tenant-b", "same").isEmpty());
    }

    private static SecureRandom seeded() {
        SecureRandom random = new SecureRandom(new byte[] { 1, 2, 3, 4 });
        random.setSeed(7L);
        return random;
    }
}
